package com.solar23040.bitaudio.security

import java.io.ByteArrayOutputStream
import java.nio.file.Files
import java.nio.file.Path
import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * SEC-016 regression guard: the committed docs-v1 vector, generated by
 * `security/attack-tests/contract_vector.py`, must verify with the production
 * `:crypto` implementation, and the TTL byte must stay outside the signature.
 */
class ContractVectorTest {

    @Test
    fun `docs v1 contract vector verifies with production crypto`() {
        val text = Files.readString(vectorPath())
        val pubkey = hex(field(text, "identity_pubkey_hex"))
        val channelKey = hex(field(text, "channel_key_hex"))
        val timestampMs = Regex("\"timestamp_ms\":\\s*(\\d+)")
            .find(text)!!.groupValues[1].toLong()
        val expectedChannelId = field(text, "channel_id_hex")
        val expectedSenderId = field(text, "sender_id_hex")
        val expectedPlaintext = hex(field(text, "plaintext_hex"))
        val frames = Regex("\"frame_hex\":\\s*\"([0-9a-f]+)\"")
            .findAll(text)
            .map { hex(it.groupValues[1]) }
            .toList()

        assertTrue("contract vector has no frames", frames.size >= 2)
        assertEquals(
            "ChannelKeys.channelId drifted from docs v1",
            expectedChannelId,
            FramesBytes.toHex(com.bitaudio.crypto.ChannelKeys.channelId(channelKey)),
        )
        assertEquals(
            "RotatingSenderId drifted from docs v1",
            expectedSenderId,
            FramesBytes.toHex(
                com.bitaudio.crypto.RotatingSenderId.derive(channelKey, pubkey, timestampMs),
            ),
        )

        val crypto = TestCrypto.default()
        val rebuilt = ByteArrayOutputStream()
        for (frame in frames) {
            val canonical = frame.copyOfRange(0, Frames.HEADER_PREFIX).also {
                it[Frames.TTL_OFFSET] = 0
            }
            val signature = frame.copyOfRange(Frames.HEADER_PREFIX, Frames.HEADER)
            val payload = frame.copyOfRange(Frames.HEADER, frame.size)
            assertTrue(
                "contract-vector signature rejected by :crypto",
                com.bitaudio.crypto.PacketCrypto.verifyPacket(
                    crypto,
                    pubkey,
                    canonical,
                    payload,
                    signature,
                ),
            )
            val plaintext = com.bitaudio.crypto.PacketCrypto.openPayload(
                crypto,
                channelKey,
                canonical,
                payload,
            )
            assertTrue("contract-vector AEAD open failed", plaintext != null)
            rebuilt.write(plaintext!!)
        }
        assertArrayEquals("reassembled contract vector mismatch", expectedPlaintext, rebuilt.toByteArray())

        // Relays decrement TTL without re-signing; the signature and AAD must
        // still verify at the next hop (SEC-002).
        val relayed = frames[0].copyOf().also { it[Frames.TTL_OFFSET] = 4 }
        val canonical = relayed.copyOfRange(0, Frames.HEADER_PREFIX).also {
            it[Frames.TTL_OFFSET] = 0
        }
        val payload = relayed.copyOfRange(Frames.HEADER, relayed.size)
        assertTrue(
            "TTL decrement broke signature verification",
            com.bitaudio.crypto.PacketCrypto.verifyPacket(
                crypto,
                pubkey,
                canonical,
                payload,
                relayed.copyOfRange(Frames.HEADER_PREFIX, Frames.HEADER),
            ),
        )
        assertTrue(
            "TTL decrement broke AEAD open",
            com.bitaudio.crypto.PacketCrypto.openPayload(
                crypto,
                channelKey,
                canonical,
                payload,
            ) != null,
        )
    }

    private fun vectorPath(): Path {
        val configured = System.getProperty("security.contractVector")
        if (configured != null && Files.exists(Path.of(configured))) return Path.of(configured)
        val candidates = listOf(
            Path.of("contract-vectors.json"),
            Path.of("../contract-vectors.json"),
            Path.of("../../security/contract-vectors.json"),
        )
        return candidates.firstOrNull { Files.exists(it) }
            ?: error("security/contract-vectors.json not found (run from the repo root)")
    }

    private fun field(text: String, name: String): String =
        Regex("\"$name\":\\s*\"([0-9a-f]+)\"").find(text)!!.groupValues[1]

    private fun hex(value: String): ByteArray =
        value.chunked(2).map { it.toInt(16).toByte() }.toByteArray()
}

internal object TestCrypto {
    fun default(): com.bitaudio.crypto.Crypto =
        com.bitaudio.crypto.DefaultCrypto(
            com.bitaudio.crypto.IdentityManager(
                com.bitaudio.crypto.InMemorySecretStore(),
            ),
        )
}

internal object FramesBytes {
    fun toHex(value: ByteArray): String = value.joinToString("") { "%02x".format(it.toInt() and 0xFF) }
}
